L22_1.m_Pos = "R"
L22_1.m_Talk_KOREA = "여기 챔버 대균열은 다른 도시와 달리, 지하 깊은 곳에 위치하기 때문이야."
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "ここチェンバーの大亀裂は他の都市とは違って、地下の深い場所にあるからだ。"
L22_1.m_Talk_ENG = "Chamber's Grand Dimension Crevice is unlike those of the other cities. It's located deep underground."
L22_1.m_Talk_TWN = "強巴的大峽谷與其他城市不同，開在了地下深處。"
L22_1.m_Talk_SCN = "会议室的大裂谷与其他城市不同，开在了地下深处。"
L22_1.m_Talk_DEU = "Chamber's Grand Dimension Crevice is unlike those of the other cities. It's located deep underground."
L22_1.m_Talk_FRA = "Chamber's Grand Dimension Crevice is unlike those of the other cities. It's located deep underground."
L23_1 = {}
