L23_1.m_Pos = "R"
L23_1.m_Talk_KOREA = "이런 곳에는 거대한 차원 함선이 진입하기 쉽지 않거든."
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "こういった場所では巨大な次元艦船だと出入りしづらいんでな。"
L23_1.m_Talk_ENG = "Also, it's hard for something as massive as a dimensional ship to enter a place like this."
