L26_1.m_Talk_JPN = "おお、そういえばそうだったな。"
L26_1.m_Talk_ENG = "Oh, come to think of it, you're right."
L26_1.m_Talk_TWN = "喔，聽你這麼一說，確實是這樣。"
L26_1.m_Talk_SCN = "哦，听你这么一说，确实是这样。"
L26_1.m_Talk_DEU = "Oh, come to think of it, you're right."
L26_1.m_Talk_FRA = "Oh, come to think of it, you're right."
L27_1 = {}
L27_1.m_CutScenKey_Talk = "SWANSONG_ACT2_STAGE1_START@27#Talk"
L27_1.m_CutScenProcessKey = 27
L27_1.m_CutScenID = 6800203
L27_1.m_CutScenStrID = "SWANSONG_ACT2_STAGE1_START"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "LIFTER_SWANSONG_NPC_NULL"
L27_1.m_Pos = "R"
L27_1.m_Talk_KOREA = "어쨌든 지하 대균열로 인해, 챔버의 이면세계 탐사는 독특한 방식으로 발전해왔어."
L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "とにかく地下の大亀裂の影響で、チェンバーの裏世界探査は独自の方法を発展させてきた。"
L27_1.m_Talk_ENG = "Anyway, due to the underground Grand Dimension Crevice, the Counterside expedition in Chamber has developed in a unique way."
L27_1.m_Talk_TWN = "無論如何，由於地下大峽谷的存在，強巴的異界探索就以這種獨特的方式發展起來了。"
L27_1.m_Talk_SCN = "无论如何，由于地下大裂谷的存在，会议室的异界探索就以这种独特的方式发展起来了。"
L27_1.m_Talk_DEU = "Anyway, due to the underground Grand Dimension Crevice, the Counterside expedition in Chamber has developed in a unique way."
L27_1.m_Talk_FRA = "Anyway, due to the underground Grand Dimension Crevice, the Counterside expedition in Chamber has developed in a unique way."
L28_1 = {}
L28_1.m_CutScenKey_Talk = "SWANSONG_ACT2_STAGE1_START@28#Talk"
L28_1.m_CutScenProcessKey = 28
L28_1.m_CutScenID = 6800203
L28_1.m_CutScenStrID = "SWANSONG_ACT2_STAGE1_START"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_CharStrID = "LIFTER_SWANSONG_NPC_NULL"
L28_1.m_Pos = "R"
L28_1.m_Talk_KOREA = "그래서 그 규모도 부대 단위의 태스크포스보다는 소규모 탐사대 위주지."
L28_1.m_fTalkTime = 0.03
L28_1.m_Talk_JPN = "だから、規模も部隊ごとのタスクフォースよりは、小規模の探査部隊が中心だ。"
L28_1.m_Talk_ENG = "That's why we tend to form exploration teams smaller than that of TASKFORCEs."
L28_1.m_Talk_TWN = "所以規模上也更傾向於小型探險隊，而不是部隊級別的特遣隊。"
L28_1.m_Talk_SCN = "所以规模上也更倾向于小型探险队，而不是部队级别的特遣队。"
L28_1.m_Talk_DEU = "That's why we tend to form exploration teams smaller than that of TASKFORCEs."
L28_1.m_Talk_FRA = "That's why we tend to form exploration teams smaller than that of TASKFORCEs."
