L29_1.m_Pos = "R"
L29_1.m_Talk_KOREA = "탐사가 많이 진행된 층 위주로 다니면 자네도 안전할 거야."
L29_1.m_fTalkTime = 0.03
L29_1.m_Talk_JPN = "探査が進んでいる階層を中心に移動すれば、君も安全だろうさ。"
L29_1.m_Talk_ENG = "You'll be safe as long as you stay on the floors that have already been explored a lot."
L29_1.m_Talk_TWN = "如果你主要在已經探查過的層面活動，會比較安全。"
L29_1.m_Talk_SCN = "如果你主要在已经探查过的层面活动，会比较安全。"
L29_1.m_Talk_DEU = "You'll be safe as long as you stay on the floors that have already been explored a lot."
L29_1.m_Talk_FRA = "You'll be safe as long as you stay on the floors that have already been explored a lot."
