L38_1 = "보아하니, 감시역으로 붙어 있던 금발 원숭이를 떼 놓은 모양이군."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "見たところ、監視役の金髪サルは振り切ったようだな。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "From the looks of it, the blonde monkey I put to keep an eye on you is no longer with you."
L37_1.m_Talk_ENG = L38_1
L38_1 = "看來，你已經擺脫了那個金髮猴子的監視了。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "看来，你已经摆脱了那个金发猴子的监视了。"
