L39_1 = "그 말은, 대장 말대로 이 세계에 보통 사람은 인지할 수 없는 변화가 일어났다는 거겠지."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "ということは、隊長の言うとおり普通の人間では認知できないような変化が起きているということだろう。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "That means, like Commander said, a change in the world that ordinary people can't perceive has occurred."
L38_1.m_Talk_ENG = L39_1
L39_1 = "那就是說，正如隊長所言，這個世界發生了普通人無法察覺的變化吧。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "那就是说，正如队长所言，这个世界发生了普通人无法察觉的变化吧。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "That means, like Commander said, a change in the world that ordinary people can't perceive has occurred."
