L46_1 = "대장님의 성격상, 배우로 일하고 있는 동안에는 노려질 일이 없다고 생각했는데."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "隊長の性格からして、役者として働いている間は狙われることはないと思っていたのですが。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Given Commander's personality, he said that I wouldn't be targeted while I worked as an actress."
