L48_1 = "그 눈……. 그 <color=#ffd34c>운명을 꿰뚫는 눈</color>으로 제 모습을 간파해 낸 건가요?"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
