L47_1.m_Talk_JPN = L48_1
L48_1 = "That eye... The <color=#ffd34c>eye that sees through fate</color>. Did you figure out who I was with that?"
L47_1.m_Talk_ENG = L48_1
L48_1 = "那只眼睛……你是用那<color=#ffd34c>洞悉命運的眼睛</color>看穿的嗎？"
L47_1.m_Talk_TWN = L48_1
L48_1 = "那只眼睛……你是用那<color=#ffd34c>洞悉命运的眼睛</color>看穿的吗？"
