L50_1 = "어떤 흉내를 내든 간, 네 과거는 불로 지진 낙인처럼 지워질 일 없을 테니까."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "誰を真似ようが、お前の過去は焼印のように消えないだろうからな。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Whoever you try to pretend to be, your past will never be erased like a brand by fire."
L49_1.m_Talk_ENG = L50_1
L50_1 = "無論你怎麼模仿，你的過去就像被火焰灼燒的烙印，永遠無法抹去。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "无论你怎么模仿，你的过去就像被火焰灼烧的烙印，永远无法抹去。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Whoever you try to pretend to be, your past will never be erased like a brand by fire."
