L7_1.m_fTalkTime = 0.03
L8_1 = "そこまで知っておきながら、なぜファーストウイングには何も教えなかったのですか？"
L7_1.m_Talk_JPN = L8_1
L8_1 = "If you knew that much, then why didn't you give Firstwing a notice in advance?"
L7_1.m_Talk_ENG = L8_1
L8_1 = "既然你知道那麼多，為什麼不告訴弗斯特薇一點消息呢？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "既然你知道那么多，为什么不告诉第一翼一点消息呢？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "If you knew that much, then why didn't you give Firstwing a notice in advance?"
L7_1.m_Talk_DEU = L8_1
